$lesson_data$::jsonb)
AS item(world text, slug text, title text, position integer, level integer, assessment text, concepts text[], steps jsonb);
--> statement-breakpoint
INSERT INTO lessons (id, slug, world_id, title, position, level, assessment, concepts, source_kind, status)
SELECT 'seed:' || i.slug, i.slug, w.id, i.title, i.position, i.level, i.assessment, i.concepts, 'authored', 'published'
FROM learning_loop_seed i JOIN worlds w ON w.slug = i.world AND w.origin = 'official'
ON CONFLICT (slug) DO NOTHING;
--> statement-breakpoint
INSERT INTO lesson_versions (id, lesson_id, version, published_at)
SELECT l.id || ':v1', l.id, 1, now() FROM lessons l JOIN learning_loop_seed i ON l.id = 'seed:' || i.slug
ON CONFLICT (lesson_id, version) DO NOTHING;
--> statement-breakpoint
UPDATE lessons l SET current_version_id = v.id
FROM lesson_versions v JOIN learning_loop_seed i ON v.lesson_id = 'seed:' || i.slug AND v.version = 1
WHERE l.id = v.lesson_id AND l.current_version_id IS NULL;
--> statement-breakpoint
INSERT INTO steps (id, lesson_version_id, idx, public, secret)
SELECT coalesce(step.value->>'id', i.slug || '-' || (step.idx - 1)), l.current_version_id, step.idx - 1,
  step.value->'public', step.value->'secret'
FROM learning_loop_seed i JOIN lessons l ON l.id = 'seed:' || i.slug
CROSS JOIN LATERAL jsonb_array_elements(i.steps) WITH ORDINALITY step(value, idx)
ON CONFLICT (id) DO NOTHING;
--> statement-breakpoint
UPDATE lessons l SET position = CASE l.slug WHEN 'variables-1' THEN 1 ELSE 2 END
FROM worlds w WHERE l.world_id = w.id AND w.origin = 'official'
AND ((w.slug = 'variables' AND l.slug = 'variables-1') OR (w.slug = 'loops' AND l.slug = 'loops-1'));
